import Foundation

/// Bundled walking-pet animations for the start page (v0.4.9, item 9).
/// All artwork is EXTERNAL material under bundle-friendly licenses —
/// no code-drawn animals. Base64-embedded because the build pipeline
/// pushes UTF-8 text only (same reason as icon.b64). Sources:
///   cat     — "Walking Cat Sprites" by cez02, OpenGameArt, CC-BY 4.0
///             (sprite sheet converted to GIF, frames unmodified)
///   dog     — "Dog Walk sprite and bone" by kirard, OpenGameArt, CC0
///             (sprite sheet converted to GIF, frames unmodified)
///   duck    — "Cartoon steamer duck walking animation" by Drummyfish,
///             Wikimedia Commons, CC0 (GIF used as-is)
///   penguin — "FOWL ANIMAL PENGUIN" by segel, OpenGameArt, CC0
///             (idle frames downscaled and assembled into a GIF)
enum PetAssets {
    static func gifData(for pet: HomePet) -> Data? {
        let chunks: [String]
        switch pet {
        case .cat: chunks = catChunks
        case .dog: chunks = dogChunks
        case .duck: chunks = duckChunks
        case .penguin: chunks = penguinChunks
        case .none: return nil
        }
        return Data(base64Encoded: chunks.joined())
    }

